package sqltype

import (
	"context"
	"fmt"
	"testing"
)

// Constants are independent PG18 oracle identities, not generated by the
// provider under test. Stored-type admission is a separate engine boundary.
func TestOrderingBtreeIdentity(t *testing.T) {
	cases := []struct {
		id  ID
		oid uint32
	}{
		{Bool, 10003}, {BPChar, 10004}, {Bytea, 10006}, {Char, 10007}, {Date, 3122},
		{Float4, 10012}, {Float8, 3123}, {Int2, 1979}, {Int4, 1978}, {Int8, 3124},
		{Interval, 10022}, {Name, 10028}, {Numeric, 3125}, {Oid, 1981}, {Regclass, 1981},
		{Text, 3126}, {VarChar, 3126}, {Time, 10038}, {Timestamp, 3128}, {Timestamptz, 3127}, {Timetz, 10041}, {UUID, 10065},
	}
	builtins := testTypes()
	for i, c := range cases {
		t.Run(builtins[c.id].Name(), func(t *testing.T) {
			base := builtins[c.id]
			usages := []Usage{base.Usage()}
			domain, err := Domain(ID(46000+2*i), "wrapped", "public.wrapped", base.Usage())
			if c.id == Char {
				if err == nil {
					t.Fatal("existing domain-over-Char exclusion changed")
				}
			} else {
				if err != nil {
					t.Fatal(err)
				}
				nested, err := Domain(ID(46001+2*i), "nested", "public.nested", domain.Usage())
				if err != nil {
					t.Fatal(err)
				}
				usages = append(usages, domain.Usage(), nested.Usage())
			}
			for _, usage := range usages {
				class, ok := DefaultIndexClass(usage.Type)
				if !ok || class.OID() != c.oid {
					t.Fatal("central default class identity diverged", class, ok, c.oid)
				}
				named, ok := LookupIndexClass(class.Name)
				if !ok || named != class {
					t.Fatal("default selection bypassed immutable class owner", class, named, ok)
				}
				provider, err := BindOrdering(usage)
				if err != nil || provider.DefaultBtreeOpclass() != c.oid {
					t.Fatalf("%s: class %d want %d: %v", usage.Type.Name(), provider.DefaultBtreeOpclass(), c.oid, err)
				}
				var got uint32
				var bindErr error
				if allocs := testing.AllocsPerRun(100, func() { p, e := BindOrdering(usage); got, bindErr = p.DefaultBtreeOpclass(), e }); allocs != 0 || bindErr != nil || got != c.oid {
					t.Fatal("ordering identity allocates or changes provider", allocs, got, bindErr)
				}
			}
			scalar, err := BindComparison(base, base)
			if err != nil || scalar.DefaultBtreeOpclass() != 0 {
				t.Fatal("scalar comparison acquired an ordering identity", scalar, err)
			}
		})
	}
}

func TestOrderingBtreeIdentityEnumDomainsAndCollations(t *testing.T) {
	enum, err := Enum(47000, "enum", "public.enum", []string{"z", "a"})
	if err != nil {
		t.Fatal(err)
	}
	domain, err := Domain(47001, "enum_domain", "public.enum_domain", enum.Usage())
	if err != nil {
		t.Fatal(err)
	}
	nested, err := Domain(47002, "nested_enum", "public.nested_enum", domain.Usage())
	if err != nil {
		t.Fatal(err)
	}
	for _, typ := range []*Descriptor{enum, domain, nested} {
		provider, err := BindOrdering(typ.Usage())
		if err != nil || provider.DefaultBtreeOpclass() != 10069 {
			t.Fatal(provider, err)
		}
		left, err := typ.Input(context.Background(), "z", -1)
		if err != nil {
			t.Fatal(err)
		}
		right, err := typ.Input(context.Background(), "a", -1)
		if err != nil {
			t.Fatal(err)
		}
		if got, err := provider.Compare(context.Background(), left, right, InputEnvironment{}); err != nil || got != -1 {
			t.Fatal("enum declaration ordering changed", got, err)
		}
	}
	for _, id := range []uint32{100, 950, 951} {
		usage := testTypes()[Text].Usage()
		usage.Collation = CollationRef{ID: id, Derivation: Default}
		p, err := BindOrdering(usage)
		if err != nil || p.DefaultBtreeOpclass() != 3126 {
			t.Fatal("collation changed the default opclass", id, p, err)
		}
	}
}

func TestOrderingBtreeIdentityRejectedProviders(t *testing.T) {
	for _, typ := range Builtins() {
		if typ.ID() != Unknown && typ.ID() != Void && typ.ID() != PgNodeTree && !typ.IsArray() {
			continue
		}
		t.Run(fmt.Sprint(typ.ID()), func(t *testing.T) {
			p, err := BindOrdering(typ.Usage())
			if err == nil || p.DefaultBtreeOpclass() != 0 {
				t.Fatal("rejected provider advertised an identity", p, err)
			}
		})
	}
	invalid := testTypes()[Text].Usage()
	invalid.Collation.ID = 999999
	for _, usage := range []Usage{{}, invalid} {
		p, err := BindOrdering(usage)
		if err == nil || p.DefaultBtreeOpclass() != 0 {
			t.Fatal("invalid usage advertised an identity", p, err)
		}
	}
}
